const AR_DIGITS = { '\u0660':'0','\u0661':'1','\u0662':'2','\u0663':'3','\u0664':'4','\u0665':'5','\u0666':'6','\u0667':'7','\u0668':'8','\u0669':'9',
  '\u06F0':'0','\u06F1':'1','\u06F2':'2','\u06F3':'3','\u06F4':'4','\u06F5':'5','\u06F6':'6','\u06F7':'7','\u06F8':'8','\u06F9':'9',
  '\u066B':'.', '\u066C':',', '\u060C':',' };
function latinDigits(v) {
  if (v === null || v === undefined) return v;
  return String(v).replace(/[\u0660-\u0669\u06F0-\u06F9\u066B\u066C\u060C]/g, c => AR_DIGITS[c]);
}
function toNum(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  let s = latinDigits(v).replace(/[^0-9.,\-]/g, '').replace(/^[.,]+|[.,]+$/g, '');
  if (!s) return null;
  if (s.includes('.') && s.includes(',')) s = s.replace(/,/g, '');
  else if (/^-?\d+,\d{1,2}$/.test(s)) s = s.replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}
const round2 = n => (n === null ? null : Math.round(n * 100) / 100);
function parseModelJson(text) {
  if (!text) throw new Error('Empty model response');
  const clean = String(text).replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('No JSON object in model response');
  return JSON.parse(clean.slice(start, end + 1));
}
function hijriToGregorian(y, m, d) {
  // Umm al-Qura calendar via Intl (built into Node). Search near an approximate date.
  const fmt = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn', { year: 'numeric', month: 'numeric', day: 'numeric', timeZone: 'UTC' });
  const epoch = Date.UTC(622, 6, 19);
  const approx = epoch + ((y - 1) * 354.367 + (m - 1) * 29.53 + (d - 1)) * 86400000;
  for (let off = -15; off <= 15; off++) {
    const t = new Date(approx + off * 86400000);
    const p = fmt.formatToParts(t);
    const g = k => parseInt((p.find(x => x.type === k) || {}).value, 10);
    if (g('year') === y && g('month') === m && g('day') === d) return t.toISOString().slice(0, 10);
  }
  return null;
}
function normalizeDate(v) {
  // Returns { iso, calendar } for 2026-10-17, 17/10/2026, 1448-04-25 (Hijri) and Arabic digits.
  if (!v) return { iso: null, calendar: null };
  const s = latinDigits(v).trim();
  let y, m, d, mt;
  if ((mt = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/))) { y = +mt[1]; m = +mt[2]; d = +mt[3]; }
  else if ((mt = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/))) { d = +mt[1]; m = +mt[2]; y = +mt[3]; }
  else { const t = Date.parse(s); return isNaN(t) ? { iso: null, calendar: null } : { iso: new Date(t).toISOString().slice(0, 10), calendar: 'gregorian' }; }
  if (m < 1 || m > 12 || d < 1 || d > 31) return { iso: null, calendar: null };
  if (y >= 1350 && y <= 1500) return { iso: hijriToGregorian(y, m, d), calendar: 'hijri' };
  const iso = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  return isNaN(Date.parse(iso)) ? { iso: null, calendar: null } : { iso, calendar: 'gregorian' };
}
function checkTaxId(raw, country) {
  // Format checks only. They do not prove the number is registered.
  if (!raw) return { tax_id: null, tax_id_check: 'missing' };
  const id = latinDigits(raw).replace(/[\s-]/g, '').toUpperCase();
  const c = (country || '').toUpperCase();
  if (c === 'SA' || (/^3\d{13}3$/.test(id) && !c)) return { tax_id: id, tax_id_check: /^3\d{13}3$/.test(id) ? 'ok_ksa_format' : 'bad_ksa_format' };
  if (c === 'AE' || (/^100\d{12}$/.test(id) && !c)) return { tax_id: id, tax_id_check: /^100\d{12}$/.test(id) ? 'ok_uae_trn_format' : 'bad_uae_trn_format' };
  return { tax_id: id, tax_id_check: 'not_checked' };
}

const cfg = $('Config').first().json;
const file = $('Watch Drive inbox folder').item.json;
const VAT_RATES = { SA: 15, AE: 5, BH: 10, OM: 5 }; // check current rates for your country before relying on them
const CURRENCY_COUNTRY = { SAR: 'SA', AED: 'AE', BHD: 'BH', OMR: 'OM' };
const issues = [];
let inv = {};
try {
  inv = parseModelJson(($json.content?.parts || []).map(p => p.text || '').join(''));
} catch (e) {
  issues.push('Gemini output could not be read: ' + ($json.error?.message || e.message));
}
const currency = String(inv.currency || cfg.defaultCurrency || '').toUpperCase()
  .replace('ر.س', 'SAR').replace('ريال', 'SAR').replace('د.إ', 'AED').replace('درهم', 'AED');
const country = CURRENCY_COUNTRY[currency] || cfg.defaultCountry;
const date = normalizeDate(inv.invoice_date_as_printed);
const seller = checkTaxId(inv.seller_vat_number, country);
const lines = (Array.isArray(inv.line_items) ? inv.line_items : []).map((l, i) => ({
  line_no: i + 1,
  description_original: l.description_original || '',
  description_en: l.description_en || '',
  quantity: toNum(l.quantity),
  unit_price: toNum(l.unit_price),
  vat_amount: toNum(l.vat_amount),
  line_total: toNum(l.line_total),
}));
const subtotal = toNum(inv.subtotal), vat = toNum(inv.vat_amount), total = toNum(inv.total), rate = toNum(inv.vat_rate_percent);
const tol = Number(cfg.amountTolerance) || 0.05;
if (!inv.invoice_number) issues.push('Missing invoice number');
if (!date.iso) issues.push(`Could not read the invoice date "${inv.invoice_date_as_printed ?? ''}"`);
if (total === null) issues.push('Missing total');
if (seller.tax_id_check.startsWith('bad')) issues.push(`Seller VAT number ${seller.tax_id} does not match the ${country} format`);
if (seller.tax_id_check === 'missing' && /tax_invoice/.test(inv.document_type || '')) issues.push('Tax invoice without a seller VAT number');
if (subtotal !== null && vat !== null && total !== null && Math.abs(subtotal + vat - total) > tol) issues.push(`Subtotal ${subtotal} + VAT ${vat} does not equal total ${total}`);
const expected = VAT_RATES[country];
if (expected && subtotal && vat !== null && Math.abs(round2(subtotal * expected / 100) - vat) > Math.max(tol, subtotal * 0.001) && vat !== 0) issues.push(`VAT ${vat} is not ${expected}% of ${subtotal}`);
const confidence = toNum(inv.confidence) ?? 0;
if (confidence < (Number(cfg.minConfidence) || 0.7)) issues.push(`Low model confidence (${confidence})`);
return { json: {
  processed_at: new Date().toISOString(),
  file_name: file.name || '',
  drive_file_id: file.id,
  document_type: inv.document_type || null,
  language: inv.language || null,
  invoice_number: inv.invoice_number ? latinDigits(inv.invoice_number) : null,
  invoice_date: date.iso,
  invoice_date_printed: inv.invoice_date_as_printed || null,
  date_calendar: date.calendar,
  seller_name_ar: inv.seller_name_ar || null,
  seller_name_en: inv.seller_name_en || null,
  seller_vat_number: seller.tax_id,
  seller_vat_check: seller.tax_id_check,
  buyer_name: inv.buyer_name || null,
  buyer_vat_number: inv.buyer_vat_number ? latinDigits(inv.buyer_vat_number) : null,
  country, currency,
  subtotal, vat_rate_percent: rate, vat_amount: vat, total,
  line_count: lines.length,
  has_qr_code: Boolean(inv.has_qr_code),
  confidence,
  needs_review: issues.length > 0,
  issues: issues.join('; '),
  line_items_json: JSON.stringify(lines),
}};

// One row per line item, linked to the invoice by number and Drive file id.
const out = [];
for (const [i] of $input.all().entries()) {
  const inv = $('Normalize Arabic and English fields').all()[i].json;
  for (const l of JSON.parse(inv.line_items_json || '[]')) {
    out.push({ json: { invoice_number: inv.invoice_number, drive_file_id: inv.drive_file_id, currency: inv.currency, ...l } });
  }
}
return out;
